 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v != 0)
    marker = min(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    shapes = set()
    for reflected in (False, True):
        for turns in range(4):
            pts = []
            for r, c in points:
                if reflected:
                    c = -c
                for _ in range(turns):
                    r, c = c, -r
                pts.append((r, c))
            min_r = min(r for r, c in pts)
            min_c = min(c for r, c in pts)
            shapes.add(tuple(sorted((r - min_r, c - min_c) for r, c in pts)))

    out = [row[:] for row in grid]
    painted = set()
    for shape in shapes:
        dh = max(r for r, c in shape) + 1
        dw = max(c for r, c in shape) + 1
        for top in range(h - dh + 1):
            for left in range(w - dw + 1):
                cells = [(top + r, left + c) for r, c in shape]
                if all(grid[r][c] == 0 for r, c in cells):
                    painted.update(cells)
    for r, c in painted:
        out[r][c] = marker
    return out
